import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class IngestionCleansingJobConfigService implements OnModuleInit {
  private readonly logger: AppLogger = new AppLogger(
    IngestionCleansingJobConfigService.name,
  );

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
  ) { }

  public async dataIngestionWorkdataRetentionDays(): Promise<number> {
    const retentionDaysEnvironment = this.configService.get<string>(
      'dataIngestionWorkdataRetentionDays',
    );

    if (retentionDaysEnvironment === undefined) {
      const appStoreValue = Number(
        await this.appConfigService.getConfigurationValue(
          'SHIPMENT_DATA_INGESTION_WORKDATA_RETENTION_DAYS',
        ),
      );
      return Number.isNaN(appStoreValue) ? 1 : appStoreValue ?? 1;
    }
    const retentionDays = Number(retentionDaysEnvironment);
    return Number.isNaN(retentionDays) ? 1 : retentionDays ?? 1;
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    if (!(await this.appConfigService.reachable())) {
      const storeNotReachableMessage = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;

      this.logger.error(storeNotReachableMessage);
      throw new Error(storeNotReachableMessage);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
        {
          key: 'dataIngestionWorkdataRetentionDays',
          value: await this.dataIngestionWorkdataRetentionDays(),
        },
      ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

  }
}

