import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { Customer } from './customer.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class CustomerService {
  private readonly logger = new AppLogger(CustomerService.name);

  public constructor(
    @InjectRepository(Customer)
    private readonly customerRepository: Repository<Customer>,
  ) {}

  // Fetch customer details by customerCode
  public async getCustomerByCode(customerCode: string): Promise<Customer> {
    try {
      const customer = await this.customerRepository.findOne({
        where: { customerCode },
      });

      if (!customer) {
        const newCustomer = new Customer();
        newCustomer.name1 = '';
        newCustomer.name2 = '';
        newCustomer.street = '';
        newCustomer.city = '';
        newCustomer.postalCode = '';
        newCustomer.country = '';
        newCustomer.customerCode = '';
        return newCustomer;
      }

      return customer;
    } catch (error) {
      const customer = new Customer();
      customer.name1 = '';
      customer.name2 = '';
      customer.street = '';
      customer.city = '';
      customer.postalCode = '';
      customer.country = '';
      customer.customerCode = '';
      this.logger.error(
        `Failed to retrieve Customer Details: ${error.message}`,
      );
      return customer;
    }
  }

  public async getCustomersByCodes(
    customerCodes: Array<string>,
    sapServer: string,
  ): Promise<Array<Customer>> {
    try {
      // Retrieve multiple customers by matching any customerCode in the provided list
      const customers = await this.customerRepository.find({
        where: { customerCode: In(customerCodes), sapServer },
      });
      return customers;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve customers by codes: ${error.message}`,
      );
      const errorNotFound =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve customers by codes',
              error,
            );
      throw errorNotFound;
    }
  }

  public async getCustomerDescByCustomerCodes(
    sapServer: string,
    customerCodes: Array<string>,
  ): Promise<Record<string, string>> {
    const responseMap: Record<string, string> = {};

    try {
      if (customerCodes.length === 0) {
        return responseMap; // No codes provided
      }

      // Retrieve customers matching the provided codes and SAP server
      const customers = await this.customerRepository.find({
        where: { customerCode: In(customerCodes), sapServer },
      });

      if (customers.length === 0) {
        throw new NotFoundException('No customers found');
      }

      // Map each requested customer code to its corresponding name
      for (const customerCode of customerCodes) {
        const customer = customers.find((c) => c.customerCode === customerCode);
        responseMap[customerCode] = customer ? String(customer.name1) : '';
      }
    } catch (error) {
      this.logger.error(
        `Failed to retrieve customer descriptions: ${error.message}`,
      );

      throw error instanceof NotFoundException
        ? error
        : new InternalServerErrorException(
            'Failed to retrieve customer descriptions',
            error,
          );
    }

    return responseMap;
  }
}

