import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository, InjectDataSource } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { TpaAssignment } from '../tpa-assignment/tpa-assignment.entity';
import { HdStatusResponseDTO } from './dtos/hdstatus-response';
import { OutboundDeliveryFilterDTO } from './dtos/outbound-delivery-filter.dto';
import { OutboundResponseDTO } from './dtos/outbound-response.dto';
import { TpaAssignmentDetailsResponseDTO } from './dtos/tpa-assignment-details-response.dto';
import { chunkValues, getUniqueValues } from './util/outbound-delivery.util';
import { AppLogger } from '@/common/logger/app-logger';
import { OutboundDeliveryResponseDTO } from '@/modules/outbound-delivery/dtos/outbound-delivery-response.dto';
import { OutboundDelivery } from '@/modules/outbound-delivery/outbound-delivery.entity';

@Injectable()
export class OutboundDeliveryService {
  private readonly logger = new AppLogger(OutboundDeliveryService.name);

  public constructor(
    @InjectRepository(OutboundDelivery)
    private readonly outboundDeliveryRepo: Repository<OutboundDelivery>,
    @InjectDataSource() private readonly dataSource: DataSource,
  ) {}

  public async getTpaCodeById(
    outbound: string,
    plant: number,
  ): Promise<OutboundDeliveryResponseDTO> {
    try {
      const result = await this.outboundDeliveryRepo
        .createQueryBuilder('od')
        .innerJoin('plant-config', 'pc', 'od.sap_server = pc.sap_server')
        .where('od.outbound = :outbound', { outbound })
        .andWhere('pc.plant = :plant', { plant })
        .select(['od.outbound as outbound', 'od.tpaCode as tpaCode'])
        .getRawOne();

      if (!result) {
        throw new NotFoundException(
          `Outbound delivery not found for outbound ${outbound} and plant ${plant}`,
        );
      }
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve outbound ${outbound} for plant ${plant}: ${error.message}`,
      );
      throw error instanceof NotFoundException
        ? error
        : new InternalServerErrorException(
            'Failed to retrieve outbound delivery',
            error,
          );
    }
  }

  public async getHdStatusById(
    outbound: string,
    plant: number,
    material: string,
  ): Promise<HdStatusResponseDTO> {
    try {
      // If numeric, pad to 18 digits; otherwise use as-is
      const queryMaterial = /^\d+$/.test(material)
        ? material.padStart(18, '0')
        : material;

      const response = await this.outboundDeliveryRepo
        .createQueryBuilder('od')
        .innerJoin(
          'plant-config',
          'pc',
          'od.sap_server = pc.sap_server AND pc.plant = :plant',
          { plant },
        )
        .innerJoinAndSelect(
          'OutboundDeliveryDtl', // Join the OutboundDeliveryDtl entity
          'odDtl',
          'od.outbound = odDtl.outbound AND odDtl.plant =:plant AND odDtl.material = :material', // Join conditions
          { plant, material: queryMaterial },
        )
        .where('od.outbound = :outbound', {
          outbound,
        })
        .select([
          'od.hdStatus AS hdStatus', // Select hdStatus from OutboundDelivery
        ])
        .getRawOne();
      if (!response) {
        throw new NotFoundException('hdStatus not found');
      }
      return response as HdStatusResponseDTO; // Casting to match return type
    } catch (error) {
      this.logger.error(`Failed to retrieve hdStatus: ${error.message}`);
      const errorToThrow =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve hdStatus',
              error,
            );
      throw errorToThrow;
    }
  }

  public async getTpaAssignmentDetailsByPlantAndOutbound(
    plant: number,
    outbound: string,
  ): Promise<TpaAssignmentDetailsResponseDTO> {
    try {
      const result = await this.outboundDeliveryRepo
        .createQueryBuilder('od')
        .innerJoin(
          'plant-config',
          'pc',
          'od.sap_server = pc.sap_server AND pc.plant = :plant',
          { plant },
        )
        .innerJoinAndSelect(
          TpaAssignment,
          'tpa',
          'tpa.plant = :plant AND tpa.truckDeparture = od.expShip AND tpa.customer = od.shipTo',
          { plant },
        )
        .where('od.outbound = :outbound', {
          outbound,
        })
        .select([
          'tpa.beginPrep AS beginPrep',
          'tpa.endPrep AS endPrep',
          'tpa.truckDeparture AS truckDeparture',
          'tpa.tpaCode AS tpaCode',
          'od.shipTo AS customer',
          'tpa.updated_at AS updatedAt',
        ])
        .orderBy('updatedAt', 'DESC')
        .getRawOne();

      if (!result) {
        const tpaAssign = new TpaAssignmentDetailsResponseDTO();
        tpaAssign.customer = '';
        tpaAssign.tpaCode = '';
        tpaAssign.beginPrep = '';
        tpaAssign.endPrep = '';
        tpaAssign.truckDeparture = '';
        return tpaAssign;
      }

      return result;
    } catch (error) {
      const tpaAssign = new TpaAssignmentDetailsResponseDTO();
      tpaAssign.customer = '';
      tpaAssign.tpaCode = '';
      tpaAssign.beginPrep = '';
      tpaAssign.endPrep = '';
      tpaAssign.truckDeparture = '';
      this.logger.error(
        `Failed to retrieve TPA assignment details: ${error.message}`,
      );
      return tpaAssign;
    }
  }

  public async getTpaAssignmentDetailsByPlantAndMultipleOutbounds(
    plant: number,
    outbounds: Array<string>,
  ): Promise<Array<Record<string, TpaAssignmentDetailsResponseDTO>>> {
    const normalizedOutbounds = getUniqueValues(outbounds);

    if (normalizedOutbounds.length === 0) {
      return [];
    }

    try {
      const result = [];

      for (const outboundChunk of chunkValues(normalizedOutbounds, 50)) {
        const chunkResult = await this.outboundDeliveryRepo
          .createQueryBuilder('od')
          .innerJoin(
            'plant-config',
            'pc',
            'pc.plant = :plant AND pc.sap_server = od.sap_server',
            { plant },
          )
          .innerJoin(
            TpaAssignment,
            'tpa',
            'tpa.plant = :plant AND tpa.truckDeparture = od.expShip AND tpa.customer = od.shipTo',
            { plant },
          )
          .where('od.outbound IN (:...outbounds)', {
            outbounds: outboundChunk,
          })
          .andWhere('od.expShip IS NOT NULL')
          .andWhere('od.shipTo IS NOT NULL')
          .select([
            'tpa.beginPrep AS beginPrep',
            'tpa.endPrep AS endPrep',
            'tpa.truckDeparture AS truckDeparture',
            'tpa.tpaCode AS tpaCode',
            'od.tpaCode AS od_tpaCode',
            'od.shipTo AS customer',
            'od.outbound AS outbound',
            'tpa.updated_at AS updatedAt',
          ])
          .orderBy('tpa.updated_at', 'DESC')
          .getRawMany();

        result.push(...chunkResult);
      }

      if (!result || result.length === 0) {
        return [];
      }

      const response: Record<string, TpaAssignmentDetailsResponseDTO> = {};

      for (const r of result) {
        if (r.outbound && !response[r.outbound]) {
          const tpaAssign = new TpaAssignmentDetailsResponseDTO();
          tpaAssign.customer = r.customer || '';
          tpaAssign.tpaCode =
            [r.od_tpaCode, r.tpaCode].find(
              (value) => value !== undefined && value !== null && value !== '',
            ) ?? '';
          tpaAssign.beginPrep = r.beginPrep || '';
          tpaAssign.endPrep = r.endPrep || '';
          tpaAssign.truckDeparture = r.truckDeparture || '';

          response[r.outbound] = tpaAssign;
        }
      }

      return Object.keys(response).length > 0 ? [response] : [];
    } catch (error) {
      this.logger.error(
        `Failed to retrieve TPA assignment details by plant and multiple outbounds: ${JSON.stringify(error)}`,
      );
      return [];
    }
  }

  public async getOutboundByCriteria(
    assignId: number,
    plant: number,
  ): Promise<Array<OutboundResponseDTO>> {
    try {
      const result = await this.outboundDeliveryRepo
        .createQueryBuilder('od')
        .innerJoin(
          TpaAssignment,
          'tpa',
          'tpa.truckDeparture = od.expShip AND tpa.plant = :plant AND tpa.customer = od.shipTo',
        )
        .where('tpa.plant = :plant AND tpa.assignId = :assignId', {
          assignId,
          plant,
        })
        .select(['od.outbound'])
        .getMany();
      // Map results to an array of strings, ensuring no undefined values
      const outboundArray: Array<OutboundResponseDTO> = result.map((item) => ({
        outbound: item.outbound ?? '',
      }));
      // Always return the mapped array, even if empty
      return outboundArray;
    } catch (error) {
      // Log the error and return an empty array as a fallback
      this.logger.error(
        `Failed to retrieve outbound delivery details: ${error.message}`,
      );
      return [];
    }
  }

  /**
   * Retrieves outbound delivery records based on the specified filters.
   * @param filterDTO - The DTO object containing filters to apply to the query.
   * @returns - A promise that resolves to an array of filtered outbound delivery records.
   * @throws {InternalServerErrorException} - If an error occurs during the query execution or mapping of results.
   * @description
   * This method builds a dynamic query to filter outbound deliveries based on the provided filter DTO.
   * It checks each filter property and, if provided, adds it to the `WHERE` clause of the query.
   * The result is then mapped to an array of `OutboundDelivery` and returned to the caller.
   */
  public async getOutboundByFilter(
    filterDTO: OutboundDeliveryFilterDTO,
  ): Promise<Array<OutboundDelivery>> {
    try {
      const queryBuild = this.outboundDeliveryRepo
        .createQueryBuilder('od') // Alias for table outbound_delivery
        .innerJoin(
          'plant-config',
          'pc',
          'od.sap_server = pc.sap_server AND pc.plant = :plant',
          { plant: filterDTO.plant },
        );

      // Build dynamically the WHERE clause based on the received optional filters
      const dynamicFilters = {
        createdAtFrom: 'od.createdAt >= :createdAtFrom',
        createdAtTo: 'od.createdAt <= :createdAtTo',
        expShipFrom: 'od.expShip >= :expShipFrom',
        expShipTo: 'od.expShip <= :expShipTo',
        hdStatus: 'od.hdStatus IN (:...hdStatus)',
        outbound: 'od.outbound = :outbound',
        processed: 'od.processed = :processed',
        shipTo: 'od.shipTo IN (:...shipTo)',
        shippingPoint: 'od.shippingPoint IN (:...shippingPoint)',
        tpaCode: 'od.tpaCode IN (:...tpaCode)',
        updatedAtFrom: 'od.updatedAt >= :updatedAtFrom',
        updatedAtTo: 'od.updatedAt <= :updatedAtTo',
      };

      for (const [key, condition] of Object.entries(dynamicFilters)) {
        const value = filterDTO[key as keyof OutboundDeliveryFilterDTO];
        if (value !== undefined && value !== null) {
          queryBuild.andWhere(condition, { [key]: value });
        }
      }

      // This reads the columns of outbound_delivery table as defined in the entity OutboundDelivery
      const entityColumns = this.dataSource
        .getMetadata(OutboundDelivery)
        .columns.map((col) => `od.${col.propertyName} AS ${col.propertyName}`);

      // This creates a list of unique valid (part of entity) columns from the list of
      // Columns specified by caller in the filterDTO in order to avoid issue by inexistent/duplicate column specified in filterDTO
      const selectedColumns = [...new Set(filterDTO.outputColumns || [])] // This part removes duplicates
        .map((col) => `od.${col} AS ${col}`)
        .filter((col) => entityColumns.includes(col));

      const finalSelection =
        selectedColumns.length > 0 ? selectedColumns : entityColumns; // Defaults to returning full list of columns if nothing valid was specified

      // GetRawMany() was chosen for performance reasons. No need to instantiate objects (as getMany() does) for each returned record since we only need the plain text details
      const result = await queryBuild
        .select(finalSelection)
        .orderBy('od.createdAt', 'ASC')
        .limit(filterDTO.rowCount ?? 100)
        .getRawMany();

      // Always return the mapped array, even if empty
      return result;
    } catch (error) {
      // Log the error and return an empty array as a fallback
      this.logger.error(
        `Failed to retrieve outbound delivery details: ${error.message}`,
      );
      return [];
    }
  }

  public async updateMultipleOutboundsAsProcessed(
    plant: number,
    outbounds: Array<string>,
  ): Promise<Array<OutboundDelivery>> {
    try {
      const records = await this.outboundDeliveryRepo
        .createQueryBuilder('od')
        .innerJoin(
          'plant-config',
          'pc',
          'od.sap_server = pc.sap_server AND pc.plant = :plant',
          { plant },
        )
        .where('od.outbound In(:...outbounds)', { outbounds })
        .select([
          'od.outbound AS outbound',
          'od.tpaCode AS tpaCode',
          'od.shippingPoint AS shippingPoint',
          'od.shipTo AS shipTo',
          'od.hdStatus AS hdStatus',
          'od.expShip AS expShip',
          'od.processed AS processed',
          'od.sapServer AS sapServer',
        ])
        .getRawMany();

      if (records.length === 0) {
        throw new NotFoundException(
          `No matching Outbound Deliveries found for plant ${plant}`,
        );
      }

      for (const record of records) {
        record.processed = true;
      }

      return await this.outboundDeliveryRepo.save(records);
    } catch (error) {
      this.logger.error(`Bulk update failed: ${error.message}`);
      throw new InternalServerErrorException(
        `Error while updating outbounds: ${error.message}`,
      );
    }
  }

  public async getOutboundByCriterias(
    assignIds: Array<number>,
    plant: number,
  ): Promise<Array<string>> {
    try {
      const result = await this.outboundDeliveryRepo
        .createQueryBuilder('od')
        .innerJoin(
          TpaAssignment,
          'tpa',
          'tpa.truckDeparture = od.expShip AND tpa.plant = :plant AND tpa.customer = od.shipTo',
        )
        .where('tpa.plant = :plant AND tpa.assignId In (:...assignIds)', {
          assignIds,
          plant,
        })
        .select(['od.outbound'])
        .getMany();
      // Map results to an array of strings, ensuring no undefined values
      const outboundArray: Array<string> = result.map(
        (item) => item.outbound ?? '',
      );
      // Always return the mapped array, even if empty
      return outboundArray;
    } catch (error) {
      // Log the error and return an empty array as a fallback
      this.logger.error(
        `Failed to retrieve outbound delivery details: ${error.message}`,
      );
      return [];
    }
  }
}

/**
 * @param values - An array of values to be divided into smaller arrays (chunks).
 * @param chunkSize - The maximum number of elements in each chunk.
 * @returns An array of chunks, where each chunk is an array of values with a length up to the specified chunk size.
 */
export function chunkValues<T>(
  values: Array<T>,
  chunkSize: number,
): Array<Array<T>> {
  const chunks: Array<Array<T>> = [];

  for (let index = 0; index < values.length; index += chunkSize) {
    chunks.push(values.slice(index, index + chunkSize));
  }

  return chunks;
}

/**
 * @param values - An array of string values that may contain duplicates, empty strings, or strings with leading/trailing whitespace.
 * @returns An array of unique, non-empty, trimmed string values.
 */
export function getUniqueValues(values?: Array<string>): Array<string> {
  return [...new Set((values ?? []).map((value) => value?.trim()))].filter(
    Boolean,
  );
}

