import { ApiOkResponse, ApiOperation, ApiParam } from '@nestjs/swagger';
import { TpaCodeParameterDTO } from './dtos/tpa-code-parameter.dto';
import { TpaCodeResponseDTO } from './dtos/tpa-code-response.dto';
import { TpaCodeService } from './tpa-code.service';

// Controller for handling customer-related requests
@Controller('tpa-code')
export class TpaCodeController {
  public constructor(private readonly tpaCodeService: TpaCodeService) {}

  @ApiOperation({
    description:
      'This endpoint allows you to retrieve the details of a tpa code based on a specific tpaId and plant.',
    summary: 'Get details of tpaCode by tpaCode and plant',
  })
  @ApiOkResponse({
    description: 'The tpacode details',
    type: TpaCodeResponseDTO,
  })
  @ApiParam({
    example: '123456',
    name: 'tpaCode',
    required: true,
    type: Number,
  })
  @ApiParam({
    example: '1146',
    name: 'plant',
    required: true,
    type: Number,
  })
  @Get('/getTpaCodeByTpaIdAndPlant/:tpaId/:plant')
  public async getTpaCodeByTpaIdAndPlant(
    @Param() parameters: TpaCodeParameterDTO,
  ): Promise<TpaCodeResponseDTO> {
    try {
      const tpaCode = await this.tpaCodeService.getTpaCodeByTpaIdAndPlant(
        parameters.tpaId,
        parameters.plant,
      );
      return tpaCode;
    } catch (error) {
      const errorNotFoundException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'An error occurred while fetching customer details',
              error,
            );
      throw errorNotFoundException;
    }
  }
}

